function ConducteurDashboard({ chantiers, offres, user }) {
  const ch = chantiers || [];
  const gainTotal = ch.filter(x=>x.statut==="termine").reduce((s,x)=>s+(x.montantConducteur||0),0);
  const gainCeMois = ch.filter(x=>x.statut==="termine" && new Date(x.updatedAt).getMonth()===new Date().getMonth()).reduce((s,x)=>s+(x.montantConducteur||0),0);
  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-r from-green-600 to-green-700 rounded-2xl p-6 text-white">
        <h2 className="text-2xl font-display font-black mb-1">Bonjour, {user.name} 👷</h2>
        <p className="text-green-200">Conducteur de Travaux · {user.city}</p>
        <p className="text-green-300 text-sm mt-1 font-mono">#{user.matricule}</p>
      </div>

      <div className="grid grid-cols-3 gap-4">
        {[
          { label:'Chantiers', value: chantiers.length, icon:'🏗️', color:'text-blue-600' },
          { label:'En cours', value: chantiers.filter(c=>c.statut==='en_cours').length, icon:'⚙️', color:'text-green-600' },
          { label:'Rapports', value: chantiers.reduce((s,c)=>s+(c.nombreRapports||0),0), icon:'📋', color:'text-amber-600' },
        ].map(s=>(
          <div key={s.label} className="bg-white rounded-2xl border border-gray-100 p-5 text-center hover:shadow-md transition-shadow">
            <p className="text-2xl mb-1">{s.icon}</p>
            <p className={`text-3xl font-display font-black ${s.color}`}>{s.value}</p>
            <p className="text-gray-500 text-xs mt-1">{s.label}</p>
          </div>
        ))}
      </div>
      {gainTotal > 0 && (
        <div className="bg-gradient-to-br from-green-900 to-green-800 rounded-2xl p-5 text-white">
          <h3 className="font-bold text-white/80 text-sm mb-3">💰 Tableau financier</h3>
          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white/10 rounded-xl p-4 text-center">
              <p className="text-xs text-green-200 mb-1">Gains ce mois</p>
              <p className="text-xl font-black">{gainCeMois > 0 ? new Intl.NumberFormat("fr-FR").format(gainCeMois) + " FCFA" : "0 FCFA"}</p>
            </div>
            <div className="bg-white/10 rounded-xl p-4 text-center">
              <p className="text-xs text-green-200 mb-1">Gains totaux</p>
              <p className="text-xl font-black">{new Intl.NumberFormat("fr-FR").format(gainTotal)} FCFA</p>
            </div>
          </div>
          <div className="mt-3 bg-white/10 rounded-xl p-3 flex justify-between items-center">
            <span className="text-green-200 text-sm">Chantiers terminés</span>
            <span className="font-bold">{ch.filter(x=>x.statut==="termine").length} chantier(s)</span>
          </div>
        </div>
      )}

      {/* Offres reçues */}
      {offres && offres.length > 0 && (
        <div className="space-y-4">
          <h3 className="font-display font-bold text-gray-900 flex items-center gap-2">🎯 Offres de mission <span className="bg-blue-600 text-white text-xs px-2 py-0.5 rounded-full">{offres.length}</span></h3>
          {offres.map((o, i) => (
            <div key={i} className="bg-white rounded-2xl border-2 border-blue-200 p-5 shadow-sm">
              <div className="flex items-start justify-between mb-3">
                <div>
                  <h4 className="font-bold text-gray-900">{o.titreChantier}</h4>
                  <p className="text-gray-500 text-sm">📍 {o.localisation} — {o.ville}</p>
                  <p className="text-gray-500 text-sm capitalize">🏗️ {o.typeChantier}</p>
                </div>
                <span className="px-3 py-1.5 bg-blue-50 text-blue-700 rounded-full text-xs font-black">{o.offre?.tarifjour ? new Intl.NumberFormat("fr-FR").format(o.offre.tarifjour)+" FCFA/jour" : "Tarif à voir"}</span>
              </div>
              {o.offre?.message && <p className="text-gray-600 text-sm italic mb-3">"{o.offre.message}"</p>}
              <div className="grid grid-cols-2 gap-2">
                <button onClick={async()=>{ try{ await (await import("../utils/api")).default.put("/conducteur-travaux/offres/"+o.demandeId+"/repondre",{reponse:"acceptee"}); window.location.reload(); }catch(e){ alert(e.response?.data?.message||"Erreur"); }}} className="py-2.5 bg-green-600 text-white rounded-xl font-bold text-sm hover:bg-green-700">✅ Accepter</button>
                <button onClick={async()=>{ const msg=prompt("Raison du refus:"); if(!msg)return; try{ await (await import("../utils/api")).default.put("/conducteur-travaux/offres/"+o.demandeId+"/repondre",{reponse:"refusee",messageReponse:msg}); window.location.reload(); }catch(e){ alert(e.response?.data?.message||"Erreur"); }}} className="py-2.5 bg-red-50 text-red-600 border border-red-200 rounded-xl font-bold text-sm hover:bg-red-100">❌ Refuser</button>
              </div>
            </div>
          ))}
        </div>
      )}
      {/* Contrat a signer */}
      {chantiers.filter(c=>c.statut==='contrat_conducteur').map(c=>(
        <div key={c._id} className="bg-white rounded-2xl border-2 border-purple-300 p-5 shadow-sm">
          <div className="flex items-center gap-3 mb-3">
            <span className="text-3xl">📄</span>
            <div>
              <h4 className="font-bold text-gray-900">{c.titreChantier}</h4>
              <p className="text-gray-500 text-sm">📍 {c.localisation} — {c.ville}</p>
            </div>
          </div>
          <div className="bg-purple-50 border border-purple-200 rounded-xl p-3 mb-3">
            <p className="text-purple-700 text-sm font-semibold">Contrat pret a signer !</p>
            <p className="text-purple-600 text-xs mt-1">Veuillez signer votre contrat pour demarrer la mission.</p>
          </div>
          <a href={`${process.env.REACT_APP_API_URL}/api/conducteur-travaux/contrat-conducteur/${c._id}`} target="_blank" rel="noopener noreferrer" className="block w-full py-2.5 mb-2 bg-blue-50 text-blue-700 border border-blue-200 rounded-xl font-bold text-sm text-center hover:bg-blue-100">
            📄 Lire le contrat PDF
          </a>
          <button onClick={async()=>{ if(!window.confirm("Confirmer la signature du contrat ?")) return; try{ const {default:api}=await import("../utils/api"); await api.put("/conducteur-travaux/demandes/"+c._id+"/valider-contrat-conducteur",{}); window.location.reload(); }catch(e){ alert(e.response?.data?.message||"Erreur"); }}} className="w-full py-2.5 bg-purple-600 text-white rounded-xl font-bold text-sm hover:bg-purple-700">
            ✍️ Signer le contrat
          </button>
        </div>
      ))}
      {chantiers.length === 0 ? (
        <div className="text-center py-16 bg-white rounded-2xl border border-gray-100">
          <div className="text-5xl mb-3">🏗️</div>
          <h3 className="text-lg font-bold text-gray-700 mb-2">Aucun chantier assigné</h3>
          <p className="text-gray-400 text-sm">L'équipe B.Y.H va vous assigner un chantier prochainement</p>
        </div>
      ) : (
        <div className="space-y-4">
          <h3 className="font-display font-bold text-gray-900">Mes chantiers</h3>
          {chantiers.map(c => (
            <div key={c._id} className="bg-white rounded-2xl border border-gray-100 p-5 shadow-sm hover:shadow-md transition-shadow">
              <div className="flex items-start justify-between mb-3">
                <div>
                  <h4 className="font-bold text-gray-900">{c.titreChantier}</h4>
                  <p className="text-gray-500 text-sm">📍 {c.localisation} — {c.ville}</p>
                  <p className="text-gray-400 text-sm">👤 Client : {c.client?.name}</p>
                </div>
                <span className="px-3 py-1 bg-green-50 text-green-700 rounded-full text-xs font-bold">🏗️ En cours</span>
              </div>
              <div className="mb-3">
                <div className="flex justify-between text-sm mb-1">
                  <span className="text-gray-500">Avancement</span>
                  <span className="font-bold text-green-600">{c.avancementGlobal || 0}%</span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2">
                  <div className="bg-green-600 rounded-full h-2" style={{width:`${c.avancementGlobal||0}%`}}/>
                </div>
              </div>
              <Link to={`/conducteur-travaux/chantier/${c._id}`}
                className="block w-full py-2.5 bg-green-600 text-white rounded-xl font-bold text-sm text-center hover:bg-green-700">
                📝 Voir et soumettre des rapports →
              </Link>
            </div>
          ))}
        </div>
      )}

      <div className="bg-white rounded-2xl border border-gray-100 p-5">
        <h3 className="font-bold text-gray-900 mb-3">Accès rapide</h3>
        <div className="grid grid-cols-2 gap-3">
          {[
            { to:'/conducteur-travaux/chantier', icon:'🏗️', label:'Mes chantiers' },
            { to:'/messages', icon:'💬', label:'Messages' },
            { to:'/profile', icon:'👤', label:'Mon profil' },
          ].map(l=>(
            <Link key={l.to} to={l.to}
              className="flex items-center gap-3 p-3 rounded-xl border border-gray-100 hover:border-green-200 hover:bg-green-50 transition-all">
              <span className="text-xl">{l.icon}</span>
              <span className="text-sm font-semibold text-gray-700">{l.label}</span>
            </Link>
          ))}
        </div>
      </div>
    </div>
  );
}

